import java.util.concurrent.*;
import java.util.stream.IntStream;

public class VtDemo {
    public static void main(String[] args) throws Exception {
        Semaphore limit = new Semaphore(50);                     // 限制对下游的并发，而不是池化
        try (ExecutorService es = Executors.newVirtualThreadPerTaskExecutor()) {
            IntStream.range(0, 10_000).forEach(i -> es.submit(() -> {
                limit.acquire();
                try {
                    Thread.sleep(1000);                          // 模拟调用 LLM/HTTP，会卸载不占载体线程
                } finally {
                    limit.release();
                }
                return i;
            }));
        }   // try-with-resources 会等待所有任务结束
        Thread vt = Thread.ofVirtual().name("vt-1").start(() -> System.out.println("hello"));
        vt.join();
    }
}
