class Sum extends RecursiveTask<Long> {
  int[] a; int l,r;
  protected Long compute() {
    if (r-l <= 10000) { long s=0; for(int i=l;i<r;i++) s+=a[i]; return s; }
    int m=(l+r)/2;
    Sum left=new Sum(a,l,m), right=new Sum(a,m,r);
    left.fork();
    long rsum=right.compute();
    return left.join()+rsum;
  }
}
